import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Archive entries:", names)
    print()

    # workbook -> sheets
    wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb_xml.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("Sheets:", sheets)

    # workbook rels
    rels_xml = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels_xml:
        rel_map[rel.get('Id')] = rel.get('Target')
    print("Rels:", rel_map)
    print()

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss_xml = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_xml.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for sheet_name, rid in sheets:
        target = rel_map[rid]
        if target.startswith('/'):
            target = target[1:]
        else:
            target = 'xl/' + target
        print(f"--- Sheet: {sheet_name} ({target}) ---")
        sheet_xml = ET.fromstring(z.read(target))
        sheet_data = sheet_xml.find('m:sheetData', NS)
        rows = []
        for row in sheet_data.findall('m:row', NS):
            r = int(row.get('r'))
            cells = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None:
                    raw = v.text
                    if t == 's':
                        val = shared[int(raw)]
                    elif t == 'b':
                        val = raw == '1'
                    elif t == 'inlineStr':
                        is_el = c.find('m:is', NS)
                        val = ''.join(tt.text or '' for tt in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                    else:
                        val = raw
                cells[col_to_idx(ref)] = val
            if cells:
                rows.append((r, cells))
        for r, cells in sorted(rows):
            print(r, cells)
        print()

